// SidebarPreview aggregator（runtime RPC 路徑）：project.json + timeline/memory/todo -> 5 區塊資料
// 5s 記憶體快取；preview.changed 事件清快取
//
// 注意：靜態 workspace client 無法 host.call（已知限制#2），SidebarPreview 日常資料
// 走 build-time embed（build.js --workspace）；本模組只在 cordis-loader 正常啟動、
// harness 可用的動態路徑下提供 runtime 資料（RPC getPreview）。
//
// P0.4.1：stats/activity 改為真實資料（todo.jsonl / memory.jsonl / timeline.jsonl），
// 與 build.js 的 embed 口徑一致；刪除已死的 writePreviewCache（webServer 路由方案遺留）。

import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { todoStats, recentTimeline, techStackToType, activeTodos, isCoreMemory } from "../store/brain-logic.js";
import { housekeepMemories, persistHousekeep } from "../memory/admit.js";
import { sanitizeProjectDescription } from "../../scanner.js";
import { mergeStackWithArchitecture, mergeTechStackWithArchitecture } from "../../stack-taxonomy.js";
import { buildProjectBriefing } from "../memory/briefing.js";
import { buildSessionGraph } from "../memory/session-graph.js";

const CACHE_TTL_MS = 5000;
const cache = new Map(); // projectPath -> { ts, data }

export function attachFamiliarity(data, parts) {
  const project = (parts && parts.project) || (data && data.project) || null;
  const brain = {
    project,
    architecture: (parts && parts.architecture) || (data && data.architecture) || null,
    timeline: (parts && parts.timeline) || (data && data.timelineAll) || [],
    memories: (parts && parts.memories) || (data && data.memoriesAll) || [],
    todos: (parts && parts.todos) || (data && data.todos) || [],
    architectureStale: Boolean(project && project.architectureStale),
  };
  if (data) {
    data.briefing = buildProjectBriefing(brain);
    data.sessionGraph = buildSessionGraph(brain);
  }
  return data;
}

export function invalidateAggregatorCache(projectPath) {
  if (projectPath) {
    cache.delete(projectPath);
  } else {
    cache.clear();
  }
}

function readJsonSync(filePath) {
  if (!existsSync(filePath)) return null;
  try {
    return JSON.parse(readFileSync(filePath, "utf8"));
  } catch (e) {
    return { __error: String((e && e.message) || e) };
  }
}

function readJsonlSync(filePath) {
  if (!existsSync(filePath)) return [];
  const out = [];
  for (const line of readFileSync(filePath, "utf8").split("\n")) {
    const s = line.trim();
    if (!s) continue;
    try { out.push(JSON.parse(s)); } catch (e) { /* skip bad line */ }
  }
  return out;
}

// 只在記憶體裡整理一遍供展示，絕不回寫。
// 這條是同步路徑，用 writeFileSync 落盤的話會繞過 write-lock，和非同步的 admit /
// 人工編輯互相覆蓋。落盤交給 ensureHousekeepOnRead 與 persistHousekeep。
function readMemoriesHousekeptSync(filePath) {
  const memories = readJsonlSync(filePath);
  const hk = housekeepMemories(memories);
  return hk.changed ? hk.rows : memories;
}

function deriveFallbackPhase(p) {
  const now = Date.now();
  const ts = (p && (p.updatedAt || p.lastScannedAt)) || now;
  const ageMs = now - ts;
  if (ageMs < 60_000) {
    return { title: "Project Brain 已就緒", progress: { done: 1, total: 1 } };
  }
  if (ageMs < 24 * 3600_000) {
    return { title: "今日活躍", progress: { done: 1, total: 2 } };
  }
  return { title: "維護中", progress: { done: 1, total: 3 } };
}

// 有 todo 資料時：Phase = 任務進度（done/total 非 cancelled）
function derivePhase(p, todos) {
  const active = todos.filter((t) => t && t.status !== "cancelled");
  if (active.length === 0) return deriveFallbackPhase(p);
  const done = active.filter((t) => t.status === "done").length;
  const inProgress = active.filter((t) => t.status === "in_progress");
  const title = inProgress.length > 0
    ? "進行中：" + inProgress[0].title
    : "待辦 " + (active.length - done) + " 項";
  return { title: title, progress: { done: done, total: active.length } };
}

export function buildSidebarPreview(projectPath) {
  if (!projectPath) projectPath = ".";
  const cached = cache.get(projectPath);
  if (cached && (Date.now() - cached.ts) < CACHE_TTL_MS) {
    return cached.data;
  }

  const brainDir = path.join(projectPath, ".project-brain");
  const p = readJsonSync(path.join(brainDir, "project.json"));
  const architecture = readJsonSync(path.join(brainDir, "architecture.json"));
  const timeline = readJsonlSync(path.join(brainDir, "timeline.jsonl"));
  const memories = readMemoriesHousekeptSync(path.join(brainDir, "memory.jsonl"));
  const visibleMemories = memories.filter(isCoreMemory);
  const todos = readJsonlSync(path.join(brainDir, "todo.jsonl"));

  let data;
  if (!p) {
    data = { initialized: false, empty: true, projectPath };
  } else if (p.__error) {
    data = { initialized: false, error: p.__error, projectPath };
  } else {
    const activity = recentTimeline(timeline, 3).map((e) => ({
      id: e.id, title: e.title, occurredAt: e.occurredAt, eventType: e.eventType,
    }));
    const stats = todoStats(todos);
    data = {
      initialized: true,
      projectPath,
      project: {
        id: p.id,
        name: p.name,
        type: techStackToType(p.techStack),
        rootPath: p.rootPath || projectPath,
        lastUpdateAt: p.updatedAt || p.lastScannedAt || Date.now(),
        architectureStale: Boolean(p.architectureStale),
      },
      phase: derivePhase(p, todos),
      recentActivity: activity.length > 0 ? activity : (p.lastScannedAt ? [{
        id: "scan",
        title: "完成 project_init 掃描",
        occurredAt: p.lastScannedAt,
        eventType: "init",
      }] : []),
      memories: visibleMemories
        .slice()
        .sort((a, b) => (b.importance || 0) - (a.importance || 0))
        .slice(0, 3),
      todos: todos,
      architecture: architecture && !architecture.__error ? architecture : null,
      stats: {
        pendingTodos: stats.pendingTodos,
        completedTodos: stats.completedTodos,
        decisions: visibleMemories.filter((m) => m.type === "decision").length,
      },
    };
    attachFamiliarity(data, { project: p, architecture: architecture && !architecture.__error ? architecture : null, timeline, memories, todos });
  }

  cache.set(projectPath, { ts: Date.now(), data });
  return data;
}

// ─── P0.4.2 動態資料（webServer route 用）：按 workspaceRoot 非同步讀 .project-brain/ ───
// 供 HTTP route `/plugins/dsh-project-brain/preview.json` 複用，client 啟動時 fetch。
// 已生成的 workspace 直接讀檔案（零 token）；未生成返回 initialized:false（Onboarding）。
// 返回結構與 build.js 的 build-time embed 對齊，client 無需區分來源。

export async function buildWorkspacePreview(fs, workspaceRoot) {
  if (!workspaceRoot) workspaceRoot = ".";
  const root = String(workspaceRoot).replace(/[\\/]+$/, "");

  async function readJson(file) {
    try {
      const target = await fs.resolve(root + "/" + file);
      const text = await fs.readText(target);
      return JSON.parse(text);
    } catch (e) {
      return null;
    }
  }
  async function readJsonl(file) {
    let text;
    try {
      const target = await fs.resolve(root + "/" + file);
      text = await fs.readText(target);
    } catch (e) {
      return [];
    }
    const out = [];
    for (const line of String(text).split("\n")) {
      const s = line.trim();
      if (!s) continue;
      try { out.push(JSON.parse(s)); } catch (e) { /* skip */ }
    }
    return out;
  }

  try { await persistHousekeep(fs, root, { writeTimeline: false }); } catch (e) {}

  const [p, timelineAll, memoriesAll, todosAll, codegraph, architecture] = await Promise.all([
    readJson(".project-brain/project.json"),
    readJsonl(".project-brain/timeline.jsonl"),
    readJsonl(".project-brain/memory.jsonl"),
    readJsonl(".project-brain/todo.jsonl"),
    readJson(".project-brain/codegraph.json"),
    readJson(".project-brain/architecture.json"),
  ]);

  if (!p) {
    return {
      generatedAt: Date.now(),
      initialized: false,
      workspaceRoot: root,
      project: null,
      phase: null,
      recentActivity: [],
      memories: [],
      memoriesAll: [],
      memoriesArchived: [],
      todos: [],
      timelineAll: [],
      architecture: null,
      stats: { pendingTodos: 0, completedTodos: 0, decisions: 0 },
    };
  }

  const timeline = (Array.isArray(timelineAll) ? timelineAll : []).filter(Boolean).slice().sort((a, b) => (b.occurredAt || 0) - (a.occurredAt || 0));
  const coreMemories = (Array.isArray(memoriesAll) ? memoriesAll : []).filter(isCoreMemory);
  const dormantMemories = (Array.isArray(memoriesAll) ? memoriesAll : []).filter((m) => m && m.status === "dormant");
  const visibleMemories = coreMemories;
  const recentActivity = timeline.slice(0, 5).map((e) => ({ id: e.id, title: e.title, occurredAt: e.occurredAt, eventType: e.eventType }));
  const memories = visibleMemories.slice().sort((a, b) => (b.importance || 0) - (a.importance || 0)).slice(0, 3);
  const stats = todoStats(todosAll);
  const inProgress = todosAll.filter((t) => t && t.status === "in_progress");
  const activeForPhase = todosAll.filter((t) => t && t.status !== "cancelled");
  const phase = activeForPhase.length > 0
    ? {
        title: inProgress.length > 0 ? "進行中：" + inProgress[0].title : "待辦 " + stats.pendingTodos + " 項",
        progress: { done: stats.completedTodos, total: activeForPhase.length },
      }
    : {
        title: "已掃描（" + (p.entrypoints ? p.entrypoints.length : 0) + " 個入口）",
        progress: { done: 1, total: 1 },
      };
  const todosActive = activeTodos(todosAll);
  const todosDone = todosAll.filter((t) => t && t.status === "done");
  const todos = todosActive.concat(todosDone).slice(0, 50);

  const preview = {
    generatedAt: Date.now(),
    initialized: true,
    workspaceRoot: root,
    project: {
      id: p.id,
      name: p.name || "(unnamed)",
      type: techStackToType(p.techStack),
      rootPath: p.rootPath || root,
      description: sanitizeProjectDescription(p.description) || "",
      techStack: mergeTechStackWithArchitecture(p.techStack || {}, architecture),
      stack: mergeStackWithArchitecture(p.stack || {}, architecture),
      structure: p.structure || [],
      tooling: p.tooling || [],
      languages: p.languages || {},
      entrypoints: p.entrypoints || [],
      lastUpdateAt: p.updatedAt || p.lastScannedAt || Date.now(),
      architectureStale: Boolean(p.architectureStale),
    },
    phase: phase,
    recentActivity: recentActivity.length > 0 ? recentActivity : (p.lastScannedAt ? [{
      id: "scan",
      title: "完成 project_init 掃描",
      occurredAt: p.lastScannedAt,
      eventType: "init",
    }] : []),
    memories: memories,
    memoriesAll: coreMemories.concat(dormantMemories).slice().sort((a, b) => {
      const ac = isCoreMemory(a) ? 0 : 1;
      const bc = isCoreMemory(b) ? 0 : 1;
      if (ac !== bc) return ac - bc;
      return (b.importance || 0) - (a.importance || 0);
    }).slice(0, 50),
    // 歸檔不是刪除：頁面要能看到它們才談得上「恢復」。
    memoriesArchived: (Array.isArray(memoriesAll) ? memoriesAll : [])
      .filter((m) => m && (m.status === "archived" || m.status === "superseded"))
      .slice()
      .sort((a, b) => (b.updatedAt || b.createdAt || 0) - (a.updatedAt || a.createdAt || 0))
      .slice(0, 50),
    todos: todos,
    timelineAll: timeline.slice(0, 50),
    codegraph: codegraph,
    architecture: architecture,
    stats: {
      pendingTodos: stats.pendingTodos,
      completedTodos: stats.completedTodos,
      decisions: visibleMemories.filter((m) => m.type === "decision").length,
      archivedMemories: (Array.isArray(memoriesAll) ? memoriesAll : []).filter((m) => m && (m.status === "archived" || m.status === "superseded" || m.status === "deleted")).length,
    },
  };
  attachFamiliarity(preview, { project: p, architecture, timeline, memories: memoriesAll, todos: todosAll });
  return preview;
}
